function campaign_template_redirect(int $id,string $message): void { $_SESSION['flash_success']=$message;header('Location: campaigns.php?view=template_edit&template_id='.$id);exit; }
function campaign_admin_send_limited_test(PDO $pdo,array $campaign,int $userId): array
{
    $userStmt=$pdo->prepare("SELECT u.id,u.email,u.first_name,u.last_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=:id AND LOWER(r.name) IN ('admin','superadmin') LIMIT 1");
    $userStmt->execute([':id'=>$userId]);$user=$userStmt->fetch()?:null;
    if(!$user||!filter_var((string)$user['email'],FILTER_VALIDATE_EMAIL))return ['ok'=>false,'message'=>'Choose a valid Admin or Superadmin account.'];

    $settings=getSiteSettings($pdo);$base=emailCampaignBaseUrl($settings);$year=(int)($campaign['membership_year']??date('Y'));
    ensureMembershipTables($pdo);
    $personStmt=$pdo->prepare("SELECT p.id,p.member_number FROM people p LEFT JOIN membership_purchases mp ON mp.member_id=p.id AND mp.membership_year=:year AND mp.status<>'expired' WHERE p.owner_user_id=:user AND p.is_archived=0 ORDER BY (mp.id IS NOT NULL) DESC,p.id LIMIT 1");
    $personStmt->execute([':year'=>$year,':user'=>$userId]);$person=$personStmt->fetch()?:[];
    $first=trim((string)($user['first_name']??''));$last=trim((string)($user['last_name']??''));$email=strtolower(trim((string)$user['email']));
    $merge=array_merge(emailCampaignEventMerge($pdo,(int)($campaign['event_id']??0),$base),[
        'campaign_name'=>(string)$campaign['name'],'first_name'=>$first,'last_name'=>$last,'full_name'=>trim($first.' '.$last),
        'email'=>$email,'member_number'=>(string)($person['member_number']??''),'membership_year'=>(string)$year,
        'current_date'=>emailCampaignLocalNow()->format('j F Y'),'membership_url'=>$base.'/memberships','logbook_url'=>$base.'/logbooks',
        'message'=>'This is limited test content.','_user_id'=>$userId,'_person_id'=>(int)($person['id']??0),'_address_source'=>'account',
    ]);
    $tracking=sha1(random_bytes(32));$unsubscribe=sha1(random_bytes(32));
    $insert=$pdo->prepare("INSERT INTO email_campaign_limited_tests (campaign_id,user_id,person_id,email,category,merge_json,tracking_token,unsubscribe_token) VALUES (:campaign,:user,:person,:email,:category,:merge,:tracking,:unsubscribe)");
    $insert->execute([':campaign'=>(int)$campaign['id'],':user'=>$userId,':person'=>(int)($person['id']??0)?:null,':email'=>$email,':category'=>(string)$campaign['category'],':merge'=>json_encode($merge,JSON_UNESCAPED_SLASHES),':tracking'=>$tracking,':unsubscribe'=>$unsubscribe]);
    $limitedId=(int)$pdo->lastInsertId();$recipient=['merge_json'=>json_encode($merge,JSON_UNESCAPED_SLASHES),'tracking_token'=>$tracking,'unsubscribe_token'=>$unsubscribe];
    $payload=emailCampaignRenderRecipient($campaign,$recipient,$settings);$emailSettings=getEmailSettings($pdo);$beforeLogId=(int)$pdo->query('SELECT COALESCE(MAX(id),0) FROM email_log')->fetchColumn();
    $ok=send_logged_email($pdo,$email,subject_with_prefix($emailSettings,$payload['subject']),wrap_user_email_html($settings,$emailSettings,$payload['html'],$payload['after_footer_html']),wrap_user_email_text($settings,$emailSettings,$payload['text'],$payload['after_footer_text']),['kind'=>'campaign_limited_test','campaign_id'=>(int)$campaign['id'],'limited_test_id'=>$limitedId]);
    $logStmt=$pdo->prepare('SELECT id FROM email_log WHERE id>:after_id AND meta_json LIKE :marker ORDER BY id DESC LIMIT 1');$logStmt->execute([':after_id'=>$beforeLogId,':marker'=>'%"limited_test_id":'.$limitedId.'%']);$logId=(int)($logStmt->fetchColumn()?:0);
    $pdo->prepare('UPDATE email_campaign_limited_tests SET status=:status,email_log_id=:log,sent_at=IF(:sent=1,NOW(),NULL) WHERE id=:id')->execute([':status'=>$ok?'sent':'failed',':log'=>$logId?:null,':sent'=>$ok?1:0,':id'=>$limitedId]);
    return ['ok'=>$ok,'message'=>$ok?'Limited test sent to '.$email.'.':'Limited test was not sent. Check the email log and delivery safety settings.'];
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$alerts[]=['type'=>'danger','message'=>'Your session token expired. Please try again.'];
    else{
        $action=(string)($_POST['action']??'');
        if($action==='save_template'){
            $templateId=max(0,(int)($_POST['template_id']??0));$name=trim((string)($_POST['name']??''));$key=preg_replace('/[^a-z0-9_]+/','_',strtolower(trim((string)($_POST['template_key']??''))))?:'';
            $renderer=in_array((string)($_POST['renderer_key']??''),['freeform','membership_renewal'],true)?(string)$_POST['renderer_key']:'freeform';
            $category=in_array((string)($_POST['category']??''),['operational','general','ride_notice','renewal_reminder'],true)?(string)$_POST['category']:'general';
            $preset=array_key_exists((string)($_POST['audience_preset']??''),emailCampaignPresets())?(string)$_POST['audience_preset']:'all_users';$subject=trim((string)($_POST['subject_template']??''));$html=trim((string)($_POST['html_template']??''));
            if($name===''||$key===''||$subject===''||($renderer==='freeform'&&$html===''))$alerts[]=['type'=>'danger','message'=>'Name, key, subject and required message content must be completed.'];
            else{
                if($templateId)$stmt=$pdo->prepare('UPDATE email_campaign_templates SET template_key=:key,name=:name,category=:category,renderer_key=:renderer,audience_preset=:audience,intro_html=:intro,outro_html=:outro,subject_template=:subject,html_template=:html,text_template=:text,is_active=:active WHERE id=:id');
                else $stmt=$pdo->prepare('INSERT INTO email_campaign_templates (template_key,name,category,renderer_key,audience_preset,intro_html,outro_html,subject_template,html_template,text_template,is_system,is_active) VALUES (:key,:name,:category,:renderer,:audience,:intro,:outro,:subject,:html,:text,0,:active)');
                $params=[':key'=>$key,':name'=>$name,':category'=>$category,':renderer'=>$renderer,':audience'=>$preset,':intro'=>trim((string)($_POST['intro_html']??'')),':outro'=>trim((string)($_POST['outro_html']??'')),':subject'=>$subject,':html'=>$html,':text'=>trim((string)($_POST['text_template']??''))?:null,':active'=>!empty($_POST['is_active'])?1:0];if($templateId)$params[':id']=$templateId;
                try{$stmt->execute($params);if(!$templateId)$templateId=(int)$pdo->lastInsertId();campaign_template_redirect($templateId,'Template saved.');}catch(PDOException $e){$alerts[]=['type'=>'danger','message'=>'The template could not be saved. Check that its key is unique.'];}
            }
        } elseif($action==='save'){
            $validationAlertCount=count($alerts);
            $name=trim((string)($_POST['name']??''));$subject=trim((string)($_POST['subject_template']??''));$html=trim((string)($_POST['html_template']??''));$renderer=in_array((string)($_POST['renderer_key']??''),['freeform','membership_renewal'],true)?(string)$_POST['renderer_key']:'freeform';$templateId=max(0,(int)($_POST['template_id']??0));
            $category=in_array((string)($_POST['category']??''),['operational','general','ride_notice','renewal_reminder'],true)?(string)$_POST['category']:'general';
            $preset=array_key_exists((string)($_POST['audience_preset']??''),emailCampaignPresets())?(string)$_POST['audience_preset']:'all_users';
            $strategy=in_array((string)($_POST['address_strategy']??''),['person_first','account_only','person_only'],true)?(string)$_POST['address_strategy']:'person_first';
            $schedule=trim((string)($_POST['scheduled_at']??''));$schedule=$schedule!==''?str_replace('T',' ',$schedule).(strlen($schedule)===16?':00':''):null;
            $batch=max(1,min(500,(int)($_POST['batch_size']??25)));$eventId=max(0,(int)($_POST['event_id']??0));$year=max(2000,min(2100,(int)($_POST['membership_year']??date('Y'))));
            if($name===''||$subject===''||($renderer==='freeform'&&$html===''))$alerts[]=['type'=>'danger','message'=>'Name, subject and required message content are required.'];
            if($preset==='event_entrants'&&$eventId<=0)$alerts[]=['type'=>'danger','message'=>'Choose an event for an entrant campaign.'];
            if($schedule!==null){$scheduleDate=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$schedule,new DateTimeZone('Europe/London'));$scheduleErrors=DateTimeImmutable::getLastErrors();if(!$scheduleDate||($scheduleErrors&&($scheduleErrors['warning_count']||$scheduleErrors['error_count'])))$alerts[]=['type'=>'danger','message'=>'Enter a valid UK-local schedule date and time.'];elseif((int)$scheduleDate->format('i')%15!==0)$alerts[]=['type'=>'danger','message'=>'Schedule campaigns on a 15-minute boundary.'];else$schedule=$scheduleDate->format('Y-m-d H:i:s');}
            if(count($alerts)===$validationAlertCount){
                if($id){$s=$pdo->prepare("UPDATE email_campaigns SET name=:name,category=:category,template_id=:template,renderer_key=:renderer,intro_html=:intro,outro_html=:outro,audience_preset=:preset,event_id=:event,membership_year=:year,address_strategy=:strategy,subject_template=:subject,html_template=:html,text_template=:text,scheduled_at=:scheduled,batch_size=:batch,status=IF(status IN ('sent','sending'),status,'draft'),live_send_approved=0,approved_by_user_id=NULL,approved_at=NULL WHERE id=:id");}
                else{$s=$pdo->prepare("INSERT INTO email_campaigns (name,campaign_type,category,template_id,renderer_key,intro_html,outro_html,audience_preset,event_id,membership_year,address_strategy,subject_template,html_template,text_template,scheduled_at,batch_size,created_by_user_id) VALUES (:name,'announcement',:category,:template,:renderer,:intro,:outro,:preset,:event,:year,:strategy,:subject,:html,:text,:scheduled,:batch,:created)");}
                $p=[':name'=>$name,':category'=>$category,':template'=>$templateId?:null,':renderer'=>$renderer,':intro'=>trim((string)($_POST['intro_html']??'')),':outro'=>trim((string)($_POST['outro_html']??'')),':preset'=>$preset,':event'=>$eventId?:null,':year'=>$year,':strategy'=>$strategy,':subject'=>$subject,':html'=>$html,':text'=>trim((string)($_POST['text_template']??''))?:null,':scheduled'=>$schedule,':batch'=>$batch];
                if($id)$p[':id']=$id;else$p[':created']=(int)$currentUser['id'];$s->execute($p);if(!$id)$id=(int)$pdo->lastInsertId();campaign_admin_redirect($id,'Campaign saved. Live approval was reset.');
            }
        } elseif($id>0&&$action==='snapshot'){$result=emailCampaignSnapshotRecipients($pdo,$id);campaign_admin_redirect($id,$result['count'].' unique recipients prepared; '.$result['skipped'].' invalid or non-consenting records skipped.');}
        elseif($id>0&&$action==='send_test'){
            $to=trim((string)($_POST['test_email']??''));$campaign=campaign_admin_row($pdo,$id);
            if(!filter_var($to,FILTER_VALIDATE_EMAIL))$alerts[]=['type'=>'danger','message'=>'Enter a valid test email address.'];
            elseif($campaign){$settings=getSiteSettings($pdo);$merge=array_merge(emailCampaignEventMerge($pdo,(int)($campaign['event_id']??0),emailCampaignBaseUrl($settings)),['campaign_name'=>$campaign['name'],'first_name'=>(string)($currentUser['first_name']??'Test'),'last_name'=>(string)($currentUser['last_name']??''),'full_name'=>trim((string)($currentUser['first_name']??'').' '.(string)($currentUser['last_name']??'')),'email'=>$to,'member_number'=>'TEST','membership_year'=>(string)($campaign['membership_year']??date('Y')),'current_date'=>emailCampaignLocalNow()->format('j F Y'),'membership_url'=>emailCampaignBaseUrl($settings).'/memberships','logbook_url'=>emailCampaignBaseUrl($settings).'/logbooks','message'=>'This is test content.']);$fake=['merge_json'=>json_encode($merge),'tracking_token'=>'test','unsubscribe_token'=>'test'];$payload=emailCampaignRenderRecipient($campaign,$fake,$settings);$emailSettings=getEmailSettings($pdo);$ok=send_logged_email($pdo,$to,subject_with_prefix($emailSettings,$payload['subject']),wrap_user_email_html($settings,$emailSettings,$payload['html'],$payload['after_footer_html']),wrap_user_email_text($settings,$emailSettings,$payload['text'],$payload['after_footer_text']),['kind'=>'campaign_test','campaign_id'=>$id]);$alerts[]=['type'=>$ok?'success':'warning','message'=>$ok?'Test email sent.':'Test email was not sent. Check the email log and delivery safety settings.'];}
        } elseif($id>0&&$action==='send_limited_test'){
            $campaign=campaign_admin_row($pdo,$id);
            if(!$campaign)$alerts[]=['type'=>'danger','message'=>'Campaign not found.'];
            else{$result=campaign_admin_send_limited_test($pdo,$campaign,max(0,(int)($_POST['limited_test_user_id']??0)));$alerts[]=['type'=>$result['ok']?'success':'warning','message'=>$result['message']];}
        } elseif($id>0&&$action==='schedule'){
            $campaign=campaign_admin_row($pdo,$id);$count=$campaign?(int)$campaign['recipient_count']:0;
            if($count<=0)$alerts[]=['type'=>'danger','message'=>'Prepare the recipient snapshot before scheduling.'];
            elseif($roleKey!=='superadmin')$alerts[]=['type'=>'danger','message'=>'Only a Superadmin can approve a live campaign.'];
            else{$scheduled=trim((string)($campaign['scheduled_at']??''))?:emailCampaignLocalNow()->format('Y-m-d H:i:s');$s=$pdo->prepare("UPDATE email_campaigns SET status='scheduled',scheduled_at=:scheduled,live_send_approved=1,approved_by_user_id=:user,approved_at=NOW() WHERE id=:id");$s->execute([':scheduled'=>$scheduled,':user'=>(int)$currentUser['id'],':id'=>$id]);campaign_admin_redirect($id,'Campaign approved and scheduled. The global campaign live-send lock still applies.');}
        }
    }
}

