      <div class="row g-3"><div class="col-md-8"><label class="form-label">Campaign name</label><input class="form-control" name="name" value="<?php echo h((string)$campaign['name']); ?>" required></div><div class="col-md-4"><label class="form-label">Category</label><select class="form-select" name="category"><option value="operational" <?php echo $campaign['category']==='operational'?'selected':''; ?>>Operational</option><option value="general" <?php echo $campaign['category']==='general'?'selected':''; ?>>General opt-in</option><option value="ride_notice" <?php echo $campaign['category']==='ride_notice'?'selected':''; ?>>Ride Notice opt-in</option><option value="renewal_reminder" <?php echo $campaign['category']==='renewal_reminder'?'selected':''; ?>>Renewal Reminders</option></select></div>
      <div class="col-md-4"><label class="form-label">Audience</label><select class="form-select" name="audience_preset"><?php foreach(emailCampaignPresets() as $key=>$label): ?><option value="<?php echo h($key); ?>" <?php echo $campaign['audience_preset']===$key?'selected':''; ?>><?php echo h($label); ?></option><?php endforeach; ?></select></div>
