      <div class="col-md-2"><label class="form-label">Membership year</label><input class="form-control" type="number" min="2000" max="2100" step="1" name="membership_year" value="<?php echo (int)$campaign['membership_year']; ?>"></div><div class="col-md-2"><label class="form-label">Batch size</label><input class="form-control" type="number" min="1" max="500" step="1" name="batch_size" value="<?php echo (int)$campaign['batch_size']; ?>"></div>
      <div class="col-md-4"><label class="form-label">Email address choice</label><select class="form-select" name="address_strategy"><option value="person_first" <?php echo $campaign['address_strategy']==='person_first'?'selected':''; ?>>Person first, account fallback</option><option value="account_only" <?php echo $campaign['address_strategy']==='account_only'?'selected':''; ?>>Account only</option><option value="person_only" <?php echo $campaign['address_strategy']==='person_only'?'selected':''; ?>>Person only</option></select></div><div class="col-md-4"><label class="form-label">Schedule (UK local time)</label><input class="form-control" type="datetime-local" name="scheduled_at" value="<?php echo h($campaign['scheduled_at']?date('Y-m-d\TH:i',strtotime((string)$campaign['scheduled_at'])):''); ?>" step="900"></div>
      <div class="col-12"><label class="form-label">Subject</label><input class="form-control" name="subject_template" value="<?php echo h((string)$campaign['subject_template']); ?>" required></div>
      <?php if(($campaign['renderer_key']??'freeform')==='membership_renewal'): ?><div class="col-12"><div class="alert alert-secondary py-2 mb-0">Membership Renewal structure: greeting, membership details and renewal button are generated by the system.</div></div><div class="col-12"><label class="form-label">Opening text</label><textarea class="form-control wysiwyg-field" rows="7" name="intro_html"><?php echo h((string)($campaign['intro_html']??'')); ?></textarea></div><div class="col-12"><label class="form-label">Closing text</label><textarea class="form-control wysiwyg-field" rows="7" name="outro_html"><?php echo h((string)($campaign['outro_html']??'')); ?></textarea></div><input type="hidden" name="html_template" value="<?php echo h((string)$campaign['html_template']); ?>"><input type="hidden" name="text_template" value="<?php echo h((string)$campaign['text_template']); ?>"><?php else: ?><input type="hidden" name="intro_html" value=""><input type="hidden" name="outro_html" value=""><div class="col-12"><label class="form-label">HTML message</label><textarea class="form-control wysiwyg-field" rows="12" name="html_template"><?php echo h((string)$campaign['html_template']); ?></textarea></div><div class="col-12"><label class="form-label">Plain-text message</label><textarea class="form-control" rows="7" name="text_template"><?php echo h((string)$campaign['text_template']); ?></textarea></div><?php endif; ?>
