    <?php if($id&&in_array((string)$campaign['status'],['draft','paused','scheduled'],true)): ?><div class="row g-3"><div class="col-md-4"><form method="post" class="card-soft p-3 h-100"><input type="hidden" name="csrf" value="<?php echo h($csrf); ?>"><input type="hidden" name="action" value="snapshot"><input type="hidden" name="id" value="<?php echo $id; ?>"><h6>1. Prepare recipients</h6><p class="small text-muted">Creates a deduplicated, consent-checked snapshot.</p><button class="btn btn-outline-success">Prepare snapshot</button></form></div><div class="col-md-4"><form method="post" class="card-soft p-3 h-100"><input type="hidden" name="csrf" value="<?php echo h($csrf); ?>"><input type="hidden" name="action" value="send_test"><input type="hidden" name="id" value="<?php echo $id; ?>"><h6>2. Test</h6><div class="small text-muted mb-2"><?php echo h($campaignTransportLabel); ?></div><input class="form-control mb-2" type="email" name="test_email" value="<?php echo h((string)($currentUser['email']??'')); ?>" required><button class="btn btn-outline-primary">Send test</button></form></div><div class="col-md-4"><form method="post" class="card-soft p-3 h-100"><input type="hidden" name="csrf" value="<?php echo h($csrf); ?>"><input type="hidden" name="action" value="schedule"><input type="hidden" name="id" value="<?php echo $id; ?>"><h6>3. Approve</h6><p class="small text-muted">Superadmin only. Campaign delivery also requires the global live-send switch.</p><button class="btn btn-warning" <?php echo $roleKey!=='superadmin'?'disabled':''; ?>>Approve and schedule</button></form></div></div>
    <form method="post" class="card-soft p-3 mt-3"><input type="hidden" name="csrf" value="<?php echo h($csrf); ?>"><input type="hidden" name="action" value="send_limited_test"><input type="hidden" name="id" value="<?php echo $id; ?>"><div class="row g-2 align-items-end"><div class="col-md-8"><h6>Send limited test</h6><div class="small text-muted mb-2">Uses the selected administrator's real merge fields, open tracking and unsubscribe link.</div><select class="form-select" name="limited_test_user_id" required><option value="">Choose an administrator</option><?php foreach($limitedTestUsers as $testUser): $testName=trim((string)$testUser['first_name'].' '.(string)$testUser['last_name']); ?><option value="<?php echo (int)$testUser['id']; ?>"><?php echo h(($testName!==''?$testName.' · ':'').$testUser['email'].' · '.ucfirst((string)$testUser['role'])); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><button class="btn btn-outline-primary w-100">Send limited test</button></div></div></form><?php endif; ?>
